package com.fireplatform;

import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import static org.assertj.core.api.Assertions.*;

class SimInventoryMigrationTest {
    final SimEmbeddedMigrationTest embedded=new SimEmbeddedMigrationTest();
    JdbcTemplate prepared(String ordering){return embedded.prepared(ordering);}
    String card(JdbcTemplate j,String tenant){return embedded.fixtures.card(j,tenant,UUID.randomUUID().toString());}
    void stock(JdbcTemplate j,String card,String tenant,String status,String issued,long revision){j.update("INSERT INTO sim_card_inventory(card_id,tenant_id,status,issued_to,revision,recorded_at) VALUES (?,?,?,?,?,TIMESTAMP WITH TIME ZONE '2026-01-02 03:04:05.123456+00:00')",card,tenant,status,issued,revision);}
    void change(JdbcTemplate j,String card,String tenant,long revision,String operation,String from,String to,String issued){j.update("INSERT INTO sim_card_inventory_changes(id,card_id,tenant_id,revision,operation,from_status,to_status,issued_to,reason,recorded_at,actor_user_id) VALUES (?,?,?,?,?,?,?,?,'',TIMESTAMP WITH TIME ZONE '2026-01-02 03:04:05.123456+00:00','actor')",UUID.randomUUID().toString(),card,tenant,revision,operation,from,to,issued);}
    @Test void inventoryHasOnlySixCurrentAndElevenPhysicalHistoryColumnsWithNoSeed(){var j=prepared("LOW");assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='sim_card_inventory' ORDER BY ordinal_position",String.class)).containsExactly("card_id","tenant_id","status","issued_to","revision","recorded_at");assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='sim_card_inventory_changes' ORDER BY ordinal_position",String.class)).containsExactly("id","card_id","tenant_id","revision","operation","from_status","to_status","issued_to","reason","recorded_at","actor_user_id");for(String table:List.of("sim_card_inventory","sim_card_inventory_changes")){assertThat(j.queryForObject("SELECT COUNT(*) FROM "+table,Long.class)).isZero();assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name=? AND is_nullable='YES'",String.class,table)).isEmpty();assertThat(j.queryForObject("SELECT datetime_precision FROM information_schema.columns WHERE table_name=? AND column_name='recorded_at'",Integer.class,table)).isEqualTo(6);}}
    @Test void zeroUnsafeRevisionVirtualStatusAndRecipientContradictionsAreDatabaseErrors(){var j=prepared("HIGH");String card=card(j,"a");for(long revision:new long[]{0,-1,9_007_199_254_740_992L})assertThatThrownBy(()->stock(j,card,"a","AVAILABLE","",revision)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->stock(j,card,"a","UNREGISTERED","",1)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->stock(j,card,"a","ISSUED","",1)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->stock(j,card,"a","AVAILABLE","recipient",1)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->stock(j,card,"a","SCRAPPED","recipient",1)).isInstanceOf(DataAccessException.class);stock(j,card,"a","ISSUED","ordinary note",1);}
    @Test void currentAndHistoryHaveCompositeSameTenantParentsAndUniqueRevisions(){var j=prepared("LOW");String card=card(j,"a"),missing=UUID.randomUUID().toString();assertThatThrownBy(()->stock(j,card,"b","AVAILABLE","",1)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->stock(j,missing,"a","AVAILABLE","",1)).isInstanceOf(DataAccessException.class);stock(j,card,"a","AVAILABLE","",1);assertThatThrownBy(()->change(j,card,"b",1,"RECEIVE","UNREGISTERED","AVAILABLE","")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,missing,"a",1,"RECEIVE","UNREGISTERED","AVAILABLE","")).isInstanceOf(DataAccessException.class);change(j,card,"a",1,"RECEIVE","UNREGISTERED","AVAILABLE","");assertThatThrownBy(()->change(j,card,"a",1,"RECEIVE","UNREGISTERED","AVAILABLE","")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->j.update("UPDATE sim_card_inventory_changes SET id='NOT-UUID'")).isInstanceOf(DataAccessException.class);}
    @Test void directIssueRecoverAndScrapFromUnregisteredAreAllowedManualRecords(){var j=prepared("HIGH");for(String operation:List.of("ISSUE","RECOVER","SCRAP")){String card=card(j,"a"),target=operation.equals("ISSUE")?"ISSUED":operation.equals("SCRAP")?"SCRAPPED":"AVAILABLE",issued=operation.equals("ISSUE")?"plain destination":"";stock(j,card,"a",target,issued,1);change(j,card,"a",1,operation,"UNREGISTERED",target,issued);}assertThat(j.queryForObject("SELECT COUNT(*) FROM sim_card_inventory_changes",Long.class)).isEqualTo(3);}
    @Test void firstHistoryMustBeUnregisteredAndLaterHistoryCannotReturnToIt(){var j=prepared("LOW");String card=card(j,"a");stock(j,card,"a","AVAILABLE","",1);assertThatThrownBy(()->change(j,card,"a",1,"RECEIVE","AVAILABLE","AVAILABLE","")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,card,"a",2,"RECEIVE","UNREGISTERED","AVAILABLE","")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,card,"a",1,"CORRECT","SCRAPPED","AVAILABLE","")).isInstanceOf(DataAccessException.class);}
    @Test void scrapOnlyAllowsRepeatScrapOrExplicitCorrectionAndEveryTargetMatchesOperation(){var j=prepared("HIGH");String card=card(j,"a");stock(j,card,"a","AVAILABLE","",4);change(j,card,"a",1,"SCRAP","UNREGISTERED","SCRAPPED","");change(j,card,"a",2,"SCRAP","SCRAPPED","SCRAPPED","");change(j,card,"a",3,"CORRECT","SCRAPPED","AVAILABLE","");change(j,card,"a",4,"RECEIVE","AVAILABLE","AVAILABLE","");for(String operation:List.of("RECEIVE","RECOVER","ISSUE")){String to=operation.equals("ISSUE")?"ISSUED":"AVAILABLE",issued=operation.equals("ISSUE")?"note":"";assertThatThrownBy(()->change(j,card,"a",5,operation,"SCRAPPED",to,issued)).isInstanceOf(DataAccessException.class);}assertThatThrownBy(()->change(j,card,"a",5,"CORRECT","AVAILABLE","AVAILABLE","")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,card,"a",5,"RECOVER","AVAILABLE","SCRAPPED","")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,card,"a",5,"ISSUE","AVAILABLE","ISSUED","")).isInstanceOf(DataAccessException.class);}
    @Test void stockRecordsNeverModifyOldMetadataOrPlatformAssociationsAndAllowIndependentReport(){var j=prepared("LOW");String card=card(j,"a");var old=embedded.fixtures.tables(j).stream().filter(table->!SimEmbeddedMigrationTest.TABLES.contains(table)).toList();assertThat(old).hasSize(50);new SimBindingMigrationTest().current(j,card,"a","a-legacy-device-0",1);var before=embedded.fixtures.facts(j,old);stock(j,card,"a","AVAILABLE","",1);change(j,card,"a",1,"RECOVER","UNREGISTERED","AVAILABLE","");assertThat(embedded.fixtures.facts(j,old)).isEqualTo(before);}
}
